window.AUTH=window.AUTH||{};window.AUTH["23-250"]={"d":"23-250","id":"2023/23-250","n":"Becerra v. San Carlos Apache Tribe","briefs":[{"k":"petitioner","label":"Brief of petitioners Xavier Becerra, Secretary of Health and Human Services, et al.","date":"2024-01-04","url":"https://www.supremecourt.gov/DocketPDF/23/23-250/294968/20240104212631524_23-250tsUnitedStates.pdf","side":"pet","n":78},{"k":"respondent","label":"Brief of respondent San Carlos Apache Tribe (as to 23-250)","date":"2024-02-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-250/300366/20240212130705181_File%20-%20SCA%20Merits%20Brief%20Final%20-%202-12-2024.pdf","side":"res","n":82},{"k":"respondent","label":"Brief of respondent Northern Arapaho Tribe (as to 23-253)","date":"2024-02-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-250/300382/20240212140134697_23-253%20bs%20Brief%20for%20Respondent%20Northern%20Arapaho%20Tribe.pdf","side":"res","n":49},{"k":"reply","label":"Reply of petitioners Xavier Becerra, Secretary of Health and Human Services, et al.","date":"2024-03-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-250/303026/20240313193617597_23-250rbUnitedStates.pdf","side":"pet","n":48}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r30_g3bi.pdf","tr":true,"items":[{"t":"case","label":"Bowsher v. Merck & Co.","cite":"460 U.S. 824","y":1983,"id":"1982/81-1273","sc":1,"sum":"The Comptroller General may inspect Merck's records of direct costs but not records of indirect costs.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Cherokee Nation of Okla. v. Leavitt","cite":"543 U.S. 631","y":2005,"id":"2004/02-1472","sc":1,"op":1,"ar":1,"sum":"The Court held that the government was legally bound to pay the contract support costs. Only in a \"special\" instance could the government break its promise to pay the costs. In this case, the government had access to sufficient unrestricted funds appropriated by Congress. Moreover, nothing in the act's language suggested it was non-binding.","sumSrc":"Oyez","by":{"0":"6, 7","1":"9, 10, 12","2":"7","3":"3"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"ar":1,"sum":"The Court held that Indian Regulatory Gaming Act does not create such an exemption. The Court reasoned that despite its parenthetical reference, the language outside the parenthetical was unambiguous and the subsection applied only to Internal Revenue Code provisions that concerned the reporting and withholding of taxes.","sumSrc":"Oyez","by":{"0":"47","3":"18"}},{"t":"case","label":"Cook Inlet Tribal Council, Inc. v. Dotomain","cite":"10 F.4th 892","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/10/892/","op":1,"by":{"0":"36","3":"8, 9"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39"}},{"t":"case","label":"Fort McDermitt Paiute & Shoshone Tribe v. Becerra","cite":"6 F.4th 6","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/6/6/","op":1,"sum":"Holding that the Secretarial amount includes only the agency’s appropriated funding.","sumSrc":"brief:0","by":{"0":"20, 24","3":"12"}},{"t":"case","label":"Luna Perez v. Sturgis Pub. Sch.","cite":"143 S. Ct. 859","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/859/","sc":1,"by":{"0":"25"}},{"t":"case","label":"Menominee Indian Tribe of Wisconsin v. United States","cite":"577 U.S. 250","y":2016,"id":"2015/14-510","sc":1,"sum":"The Court determined that there were no extraordinary circumstances out of the Menominee Indian Tribe’s control to toll the statute of limitations from running.","sumSrc":"Oyez","by":{"0":"3"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23"}},{"t":"case","label":"Oncale v. Sundowner Offshore Servs., Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"0":"40","3":"15"}},{"t":"case","label":"Oregon Dep’t of Fish & Wildlife v. Klamath Indian Tribe","cite":"473 U.S. 753","y":1985,"id":"1984/83-2148","sc":1,"sum":"In light of the terms of the 1901 Agreement and the 1864 Treaty, and certain other events in the Tribe's history, the Tribe's exclusive right to hunt and fish on the lands reserved to the Tribe by the 1864 Treaty did not survive as a special right to be free of state regulation in the ceded lands that were outside the reservation after the 1901 Agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47","3":"17"}},{"t":"case","label":"Ramah Navajo Chapter v. Lujan","cite":"112 F.3d 1455","y":1997,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/112/1455/","op":1,"by":{"0":"8, 40, 41","1":"13, 40","2":"10, 18, 46, 48","3":"15, 17"}},{"t":"case","label":"Republic of Argentina v. Weltover, Inc.","cite":"504 U.S. 607","y":1992,"id":"1991/91-763","sc":1,"sum":"The Court held that the District Court properly asserted jurisdiction under the FSIA.","sumSrc":"Oyez","by":{"0":"26, 41","3":"14"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Salazar v. Ramah Navajo Chapter","cite":"567 U.S. 182","y":2012,"id":"2011/11-551","sc":1,"ar":3,"sum":"The Court held that, under the Indian Self-Determination and Education Assistance Act, the government is required to pay all of the contract support costs incurred by a tribal contractor if payment of those costs would exceed the statutory cap on the appropriations available to pay them.","sumSrc":"Oyez","by":{"0":"4, 45","1":"5, 8, 10, 12, 21, 36, 47, 48","2":"3, 7, 52, 55","3":"8, 17"}},{"t":"case","label":"South Carolina v. Catawba Indian Tribe, Inc.","cite":"476 U.S. 498","y":1986,"id":"1985/84-782","sc":1,"sum":"The explicit redefinition of the relationship between the Federal Government and respondent Tribe reflected in the Catawba Act's clear language requires the application of the state statute of limitations to the Tribe's claim. But whether that statute bars the claim should be determined by the Court of Appeals on remand. Pp. 506-511. 740 F. 2d 305, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 18, 47","3":"18"}},{"t":"case","label":"Swinomish Indian Tribal Community v. Becerra","cite":"993 F.3d 917","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/993/917/","sum":"Rejecting that tribe’s similar attempt to conflate the two.","sumSrc":"brief:0","by":{"0":"13, 19, 25, 38","2":"25","3":"10, 19"}},{"t":"usc","label":"2 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/2/621","by":{"0":"45"}},{"t":"usc","label":"2 U.S.C. § 633","url":"https://www.law.cornell.edu/uscode/text/2/633","subs":["(b)"],"by":{"0":"45"}},{"t":"law","label":"Pub. L. No. 117-328","url":"https://www.govinfo.gov/link/plaw/117/public/328","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 95-563","url":"https://www.govinfo.gov/link/statute/92/2383","by":{"0":"11"}},{"t":"law","label":"Pub. L. No. 95-465","url":"https://www.govinfo.gov/link/statute/92/1296","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 102-154","url":"https://www.govinfo.gov/link/statute/105/1026","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"0":"7","3":"16"}},{"t":"usc","label":"25 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/25/1601","subs":["(1)"],"stext":{"head":"§1601. Congressional findings","paras":[[0,"The Congress finds the following:"],[1,"(1) Federal health services to maintain and improve the health of the Indians are consonant with and required by the Federal Government's historical and unique legal relationship with, and resulting responsibility to, the American Indian people."],[1,"(2) A major national goal of the United States is to provide the resources, processes, and structure that will enable Indian tribes and tribal members to obtain the quantity and quality of health care services and opportunities that will eradicate the health disparities between Indians and the general population of the United States."],[1,"(3) A major national goal of the United States is to provide the quantity and quality of health services which will permit the health status of Indians to be raised to the highest possible level and to encourage the maximum participation of Indians in the planning and management of those services."],[1,"(4) Federal health services to Indians have resulted in a reduction in the prevalence and incidence of preventable illnesses among, and unnecessary and premature deaths of, Indians."],[1,"(5) Despite such services, the unmet health needs of the American Indian people are severe and the health status of the Indians is far below that of the general population of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1601?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1601. Congressional findings","tname":"Indians","by":{"0":"3, 9","1":"1","2":"1, 4"}},{"t":"usc","label":"25 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/25/1602","subs":["(7)"],"stext":{"head":"§1602. Declaration of national Indian health policy","paras":[[0,"Congress declares that it is the policy of this Nation, in fulfillment of its special trust responsibilities and legal obligations to Indians—"],[1,"(1) to ensure the highest possible health status for Indians and urban Indians and to provide all resources necessary to effect that policy;"],[1,"(2) to raise the health status of Indians and urban Indians to at least the levels set forth in the goals contained within the Healthy People 2010 initiative or successor objectives;"],[1,"(3) to ensure maximum Indian participation in the direction of health care services so as to render the persons administering such services and the services themselves more responsive to the needs and desires of Indian communities;"],[1,"(4) to increase the proportion of all degrees in the health professions and allied and associated health professions awarded to Indians so that the proportion of Indian health professionals in each Service area is raised to at least the level of that of the general population;"],[1,"(5) to require that all actions under this chapter shall be carried out with active and meaningful consultation with Indian tribes and tribal organizations, and conference with urban Indian organizations, to implement this chapter and the national policy of Indian self-determination;"],[1,"(6) to ensure that the United States and Indian tribes work in a government-to-government relationship to ensure quality health care for all tribal members; and"],[1,"(7) to provide funding for programs and facilities operated by Indian tribes and tribal organizations in amounts that are not less than the amounts provided to programs and facilities operated directly by the Service."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1602?type=usc&year=mostrecent&link-type=html"},"head":"§1602. Declaration of national Indian health policy","tname":"Indians","by":{"0":"9, 23","1":"32","2":"6, 39"}},{"t":"usc","label":"25 U.S.C. § 1621e","url":"https://www.law.cornell.edu/uscode/text/25/1621e","subs":["(a)","(c)","(e)(3)(A)"],"stext":{"head":"§1621e. Reimbursement from certain third parties of costs of health services","paras":[[0,"(a) Right of recovery"],[0,"Except as provided in subsection (f), the United States, an Indian tribe, or tribal organization shall have the right to recover from an insurance company, health maintenance organization, employee benefit plan, third-party tortfeasor, or any other responsible or liable third party (including a political subdivision or local governmental entity of a State) the reasonable charges billed by the Secretary, an Indian tribe, or tribal organization in providing health services through the Service, an Indian tribe, or tribal organization, or, if higher, the highest amount the third party would pay for care and services furnished by providers other than governmental entities, to any individual to the same extent that such individual, or any nongovernmental provider of such services, would be eligible to receive damages, reimbursement, or indemnification for such charges or expenses if—"],[1,"(1) such services had been provided by a nongovernmental provider; and"],[1,"(2) such individual had been required to pay such charges or expenses and did pay such charges or expenses."],[0,"(b) Limitations on recoveries from States"],[0,"Subsection (a) shall provide a right of recovery against any State, only if the injury, illness, or disability for which health services were provided is covered under—"],[1,"(1) workers' compensation laws; or"],[1,"(2) a no-fault automobile accident insurance plan or program."],[0,"(c) Nonapplicability of other laws"],[0,"No law of any State, or of any political subdivision of a State and no provision of any contract, insurance or health maintenance organization policy, employee benefit plan, self-insurance plan, managed care plan, or other health care plan or program entered into or renewed after November 23, 1988, shall prevent or hinder the right of recovery of the United States, an Indian tribe, or tribal organization under subsection (a)."],[0,"(d) No effect on private rights of action"],[0,"No action taken by the United States, an Indian tribe, or tribal organization to enforce the right of recovery provided under this section shall operate to deny to the injured person the recovery for that portion of the person's damage not covered hereunder."],[0,"(e) Enforcement"],[0,"(1) In general"],[1,"The United States, an Indian tribe, or tribal organization may enforce the right of recovery provided under subsection (a) by—"],[2,"(A) intervening or joining in any civil action or proceeding brought—"],[3,"(i) by the individual for whom health services were provided by the Secretary, an Indian tribe, or tribal organization; or"],[3,"(ii) by any representative or heirs of such individual, or"],[2,"(B) instituting a separate civil action, including a civil action for injunctive relief and other relief and including, with respect to a political subdivision or local governmental entity of a State, such an action against an official thereof."],[0,"(2) Notice"],[1,"All reasonable efforts shall be made to provide notice of action instituted under paragraph (1)(B) to the individual to whom health services were provided, either before or during the pendency of such action."],[0,"(3) Recovery from tortfeasors"],[0,"(A) In general"],[2,"In any case in which an Indian tribe or tribal organization that is authorized or required under a compact or contract issued pursuant to the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.) 1 to furnish or pay for health services to a person who is injured or suffers a disease on or after March 23, 2010, under circumstances that establish grounds for a claim of liability against the tortfeasor with respect to the injury or disease, the Indian tribe or tribal organization shall have a right to recover from the tortfeasor (or an insurer of the tortfeasor) the reasonable value of the health services so furnished, paid for, or to be paid for, in accordance with the Federal Medical Care Recovery Act (42 U.S.C. 2651 et seq.), to the same extent and under the same circumstances as the United States may recover under that Act."],[0,"(B) Treatment"],[2,"The right of an Indian tribe or tribal organization to recover under subparagraph (A) shall be independent of the rights of the injured or diseased person served by the Indian tribe or tribal organization."],[0,"(f) Limitation"],[0,"Absent specific written authorization by the governing body of an Indian tribe for the period of such authorization (which may not be for a period of more than 1 year and which may be revoked at any time upon written notice by the governing body to the Service), the United States shall not have a right of recovery under this section if the injury, illness, or disability for which health services were provided is covered under a self-insurance plan funded by an Indian tribe, tribal organization, or urban Indian organization. Where such authorization is provided, the Service may receive and expend such amounts for the provision of additional health services consistent with such authorization."],[0,"(g) Costs and attorney's fees"],[0,"In any action brought to enforce the provisions of this section, a prevailing plaintiff shall be awarded its reasonable attorney's fees and costs of litigation."],[0,"(h) Nonapplicability of claims filing requirements"],[0,"An insurance company, health maintenance organization, self-insurance plan, managed care plan, or other health care plan or program (under the Social Security Act [42 U.S.C. 301 et seq.] or otherwise) may not deny a claim for benefits submitted by the Service or by an Indian tribe or tribal organization based on the format in which the claim is submitted if such format complies with the format required for submission of claims under title XVIII of the Social Security Act [42 U.S.C. 1395 et seq.] or recognized under section 1175 of such Act [42 U.S.C. 1320d–4]."],[0,"(i) Application to urban Indian organizations"],[0,"The previous provisions of this section shall apply to urban Indian organizations with respect to populations served by such Organizations 1 in the same manner they apply to Indian tribes and tribal organizations with respect to populations served by such Indian tribes and tribal organizations."],[0,"(j) Statute of limitations"],[0,"The provisions of section 2415 of title 28 shall apply to all actions commenced under this section, and the references therein to the United States are deemed to include Indian tribes, tribal organizations, and urban Indian organizations."],[0,"(k) Savings"],[0,"Nothing in this section shall be construed to limit any right of recovery available to the United States, an Indian tribe, or tribal organization under the provisions of any applicable, Federal, State, or tribal law, including medical lien laws."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1621e?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1621e. Reimbursement from certain third parties of costs of health services","tname":"Indians","by":{"0":"9, 23","1":"33, 7, 42","2":"5, 50, 50"}},{"t":"usc","label":"25 U.S.C. § 1621f","url":"https://www.law.cornell.edu/uscode/text/25/1621f","subs":["(a)","(a)(2)(D)","(a)(1)","(b)"],"stext":{"head":"§1621f. Crediting of reimbursements","paras":[[0,"(a) Use of amounts"],[0,"(1) Retention by program"],[1,"Except as provided in sections 1621a(a)(2) and 1680c of this title, all reimbursements received or recovered under any of the programs described in paragraph (2), including under section 1680c of this title, by reason of the provision of health services by the Service, by an Indian tribe or tribal organization, or by an urban Indian organization, shall be credited to the Service, such Indian tribe or tribal organization, or such urban Indian organization, respectively, and may be used as provided in section 1641 of this title. In the case of such a service provided by or through a Service Unit, such amounts shall be credited to such unit and used for such purposes."],[0,"(2) Programs covered"],[1,"The programs referred to in paragraph (1) are the following:"],[2,"(A) Titles XVIII, XIX, and XXI of the Social Security Act [42 U.S.C. 1395 et seq., 1396 et seq., 1397aa et seq.]."],[2,"(B) This chapter, including section 1680c of this title."],[2,"(C) Public Law 87–693 [42 U.S.C. 2651 et seq.]."],[2,"(D) Any other provision of law."],[0,"(b) No offset of amounts"],[0,"The Service may not offset or limit any amount obligated to any Service Unit or entity receiving funding from the Service because of the receipt of reimbursements under subsection (a)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1621f?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1621f. Crediting of reimbursements","tname":"Indians","by":{"0":"9, 34, 9, 34, 34","1":"33, 8, 34","2":"5, 21, 38","3":"10"}},{"t":"usc","label":"25 U.S.C. § 1641","url":"https://www.law.cornell.edu/uscode/text/25/1641","subs":["(d)(1)","(d)(2)","(a)","(c)(1)(B)","(d)","(d)(2)(A)","(c)(1)(A)"],"stext":{"head":"§1641. Treatment of payments under Social Security Act health benefits programs","paras":[[0,"(a) Disregard of Medicare, Medicaid, and CHIP payments in determining appropriations"],[0,"Any payments received by an Indian health program or by an urban Indian organization under title XVIII, XIX, or XXI of the Social Security Act [42 U.S.C. 1395 et seq., 1396 et seq., 1397aa et seq.] for services provided to Indians eligible for benefits under such respective titles shall not be considered in determining appropriations for the provision of health care and services to Indians."],[0,"(b) Nonpreferential treatment"],[0,"Nothing in this chapter authorizes the Secretary to provide services to an Indian with coverage under title XVIII, XIX, or XI 1 of the Social Security Act in preference to an Indian without such coverage."],[0,"(c) Use of funds"],[0,"(1) Special fund"],[0,"(A) 100 percent pass-through of payments due to facilities"],[2,"Notwithstanding any other provision of law, but subject to paragraph (2), payments to which a facility of the Service is entitled by reason of a provision of title XVIII or XIX of the Social Security Act [42 U.S.C. 1395 et seq., 1396 et seq.] shall be placed in a special fund to be held by the Secretary. In making payments from such fund, the Secretary shall ensure that each Service unit of the Service receives 100 percent of the amount to which the facilities of the Service, for which such Service unit makes collections, are entitled by reason of a provision of either such title."],[0,"(B) Use of funds"],[2,"Amounts received by a facility of the Service under subparagraph (A) by reason of a provision of title XVIII or XIX of the Social Security Act shall first be used (to such extent or in such amounts as are provided in appropriation Acts) for the purpose of making any improvements in the programs of the Service operated by or through such facility which may be necessary to achieve or maintain compliance with the applicable conditions and requirements of such respective title. Any amounts so received that are in excess of the amount necessary to achieve or maintain such conditions and requirements shall, subject to consultation with the Indian tribes being served by the Service unit, be used for reducing the health resource deficiencies (as determined in section 1621(c) of this title) of such Indian tribes, including the provision of services pursuant to section 1621d of this title."],[0,"(2) Direct payment option"],[1,"Paragraph (1) shall not apply to a tribal health program upon the election of such program under subsection (d) to receive payments directly. No payment may be made out of the special fund described in such paragraph with respect to reimbursement made for services provided by such program during the period of such election."],[0,"(d) Direct billing"],[0,"(1) In general"],[1,"Subject to complying with the requirements of paragraph (2), a tribal health program may elect to directly bill for, and receive payment for, health care items and services provided by such program for which payment is made under title XVIII, XIX, or XXI of the Social Security Act [42 U.S.C. 1395 et seq., 1396 et seq., 1397aa et seq.] or from any other third party payor."],[0,"(2) Direct reimbursement"],[0,"(A) Use of funds"],[2,"Each tribal health program making the election described in paragraph (1) with respect to a program under a title of the Social Security Act [42 U.S.C. 301 et seq.] shall be reimbursed directly by that program for items and services furnished without regard to subsection (c)(1), except that all amounts so reimbursed shall be used by the tribal health program for the purpose of making any improvements in facilities of the tribal health program that may be necessary to achieve or maintain compliance with the conditions and requirements applicable generally to such items and services under the program under such title and to provide additional health care services, improvements in health care facilities and tribal health programs, any health care-related purpose (including coverage for a service or service within a contract health service delivery area or any portion of a contract health service delivery area that would otherwise be provided as a contract health service), or otherwise to achieve the objectives provided in section 1602 of this title."],[0,"(B) Audits"],[2,"The amounts paid to a tribal health program making the election described in paragraph (1) with respect to a program under title XVIII, XIX, or XXI of the Social Security Act shall be subject to all auditing requirements applicable to the program under such title, as well as all auditing requirements applicable to programs administered by an Indian health program. Nothing in the preceding sentence shall be construed as limiting the application of auditing requirements applicable to amounts paid under title XVIII, XIX, or XXI of the Social Security Act."],[0,"(C) Identification of source of payments"],[2,"Any tribal health program that receives reimbursements or payments under title XVIII, XIX, or XXI of the Social Security Act shall provide to the Service a list of each provider enrollment number (or other identifier) under which such program receives such reimbursements or payments."],[0,"(3) Examination and implementation of changes"],[0,"(A) In general"],[2,"The Secretary, acting through the Service and with the assistance of the Administrator of the Centers for Medicare & Medicaid Services, shall examine on an ongoing basis and implement any administrative changes that may be necessary to facilitate direct billing and reimbursement under the program established under this subsection, including any agreements with States that may be necessary to provide for direct billing under a program under title XIX or XXI of the Social Security Act [42 U.S.C. 1396 et seq., 1397aa et seq.]."],[0,"(B) Coordination of information"],[2,"The Service shall provide the Administrator of the Centers for Medicare & Medicaid Services with copies of the lists submitted to the Service under paragraph (2)(C), enrollment data regarding patients served by the Service (and by tribal health programs, to the extent such data is available to the Service), and such other information as the Administrator may require for purposes of administering title XVIII, XIX, or XXI of the Social Security Act."],[0,"(4) Withdrawal from program"],[1,"A tribal health program that bills directly under the program established under this subsection may withdraw from participation in the same manner and under the same conditions that an Indian tribe or tribal organization may retrocede a contracted program to the Secretary under the authority of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.).2 All cost accounting and billing authority under the program established under this subsection shall be returned to the Secretary upon the Secretary's acceptance of the withdrawal of participation in this program."],[0,"(5) Termination for failure to comply with requirements"],[1,"The Secretary may terminate the participation of a tribal health program or 3 in the direct billing program established under this subsection if the Secretary determines that the program has failed to comply with the requirements of paragraph (2). The Secretary shall provide a tribal health program with notice of a determination that the program has failed to comply with any such requirement and a reasonable opportunity to correct such noncompliance prior to terminating the program's participation in the direct billing program established under this subsection."],[0,"(e) Related provisions under the Social Security Act"],[0,"For provisions related to subsections (c) and (d), see sections 1880, 1911, and 2107(e)(1)(D) 2 of the Social Security Act [42 U.S.C. 1395qq, 1396j, 1397gg(e)(1)(D)]."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1641?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1641. Treatment of payments under Social Security Act health benefits programs","tname":"Indians","by":{"0":"2, 2, 2","1":"34, 34, 7, 7, 34","2":"5, 5, 21, 26, 38, 6, 26, 43","3":"12, 10, 12, 7, 11"}},{"t":"usc","label":"25 U.S.C. § 1680c","url":"https://www.law.cornell.edu/uscode/text/25/1680c","subs":["(c)(1)(A)","(c)(1)(B)","(c)(2)"],"stext":{"head":"§1680c. Health services for ineligible persons","paras":[[0,"(a) Children"],[0,"Any individual who—"],[1,"(1) has not attained 19 years of age;"],[1,"(2) is the natural or adopted child, stepchild, foster child, legal ward, or orphan of an eligible Indian; and"],[1,"(3) is not otherwise eligible for health services provided by the Service,"],[0,"shall be eligible for all health services provided by the Service on the same basis and subject to the same rules that apply to eligible Indians until such individual attains 19 years of age. The existing and potential health needs of all such individuals shall be taken into consideration by the Service in determining the need for, or the allocation of, the health resources of the Service. If such an individual has been determined to be legally incompetent prior to attaining 19 years of age, such individual shall remain eligible for such services until 1 year after the date of a determination of competency."],[0,"(b) Spouses"],[0,"Any spouse of an eligible Indian who is not an Indian, or who is of Indian descent but is not otherwise eligible for the health services provided by the Service, shall be eligible for such health services if all such spouses or spouses who are married to members of each Indian tribe being served are made eligible, as a class, by an appropriate resolution of the governing body of the Indian tribe or tribal organization providing such services. The health needs of persons made eligible under this paragraph shall not be taken into consideration by the Service in determining the need for, or allocation of, its health resources."],[0,"(c) Health facilities providing health services"],[0,"(1) In general"],[1,"The Secretary is authorized to provide health services under this subsection through health facilities operated directly by the Service to individuals who reside within the Service unit and who are not otherwise eligible for such health services if—"],[2,"(A) the Indian tribes served by such Service unit requests such provision of health services to such individuals, and"],[2,"(B) the Secretary and the served Indian tribes have jointly determined that the provision of such health services will not result in a denial or diminution of health services to eligible Indians."],[0,"(2) ISDEAA programs"],[1,"In the case of health facilities operated under a contract or compact entered into under the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.),1 the governing body of the Indian tribe or tribal organization providing health services under such contract or compact is authorized to determine whether health services should be provided under such contract or compact to individuals who are not eligible for such health services under any other subsection of this section or under any other provision of law. In making such determinations, the governing body of the Indian tribe or tribal organization shall take into account the consideration described in paragraph (1)(B). Any services provided by the Indian tribe or tribal organization pursuant to a determination made under this subparagraph shall be deemed to be provided under the agreement entered into by the Indian tribe or tribal organization under the Indian Self-Determination and Education Assistance Act. The provisions of section 314 of Public Law 101–512 (104 Stat. 1959), as amended by section 308 of Public Law 103–138 (107 Stat. 1416), shall apply to any services provided by the Indian tribe or tribal organization pursuant to a determination made under this subparagraph."],[0,"(3) Payment for services"],[0,"(A) In general"],[2,"Persons receiving health services provided by the Service under this subsection shall be liable for payment of such health services under a schedule of charges prescribed by the Secretary which, in the judgment of the Secretary, results in reimbursement in an amount not less than the actual cost of providing the health services. Notwithstanding section 1621f of this title or any other provision of law, amounts collected under this subsection, including Medicare, Medicaid, or children's health insurance program reimbursements under titles XVIII, XIX, and XXI of the Social Security Act [42 U.S.C. 1395 et seq., 1396 et seq., 1397aa et seq.], shall be credited to the account of the program providing the service and shall be used for the purposes listed in section 1641(d)(2) of this title and amounts collected under this subsection shall be available for expenditure within such program."],[0,"(B) Indigent people"],[2,"Health services may be provided by the Secretary through the Service under this subsection to an indigent individual who would not be otherwise eligible for such health services but for the provisions of paragraph (1) only if an agreement has been entered into with a State or local government under which the State or local government agrees to reimburse the Service for the expenses incurred by the Service in providing such health services to such indigent individual."],[0,"(4) Revocation of consent for services"],[0,"(A) Single tribe service area"],[2,"In the case of a Service Area which serves only 1 Indian tribe, the authority of the Secretary to provide health services under paragraph (1) shall terminate at the end of the fiscal year succeeding the fiscal year in which the governing body of the Indian tribe revokes its concurrence to the provision of such health services."],[0,"(B) Multitribal service area"],[2,"In the case of a multitribal Service Area, the authority of the Secretary to provide health services under paragraph (1) shall terminate at the end of the fiscal year succeeding the fiscal year in which at least 51 percent of the number of Indian tribes in the Service Area revoke their concurrence to the provisions of such health services."],[0,"(d) Other services"],[0,"The Service may provide health services under this subsection to individuals who are not eligible for health services provided by the Service under any other provision of law in order to—"],[1,"(1) achieve stability in a medical emergency;"],[1,"(2) prevent the spread of a communicable disease or otherwise deal with a public health hazard;"],[1,"(3) provide care to non-Indian women pregnant with an eligible Indian's child for the duration of the pregnancy through postpartum; or"],[1,"(4) provide care to immediate family members of an eligible individual if such care is directly related to the treatment of the eligible individual."],[0,"(e) Hospital privileges for practitioners"],[0,"(1) In general"],[1,"Hospital privileges in health facilities operated and maintained by the Service or operated under a contract or compact pursuant to the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.) 1 may be extended to non-Service health care practitioners who provide services to individuals described in subsection (a), (b), (c), or (d). Such non-Service health care practitioners may, as part of the privileging process, be designated as employees of the Federal Government for purposes of section 1346(b) and chapter 171 of title 28 (relating to Federal tort claims) only with respect to acts or omissions which occur in the course of providing services to eligible individuals as a part of the conditions under which such hospital privileges are extended."],[0,"(2) Definition"],[1,"For purposes of this subsection, the term \"non-Service health care practitioner\" means a practitioner who is not—"],[2,"(A) an employee of the Service; or"],[2,"(B) an employee of an Indian tribe or tribal organization operating a contract or compact under the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.) 1 or an individual who provides health care services pursuant to a personal services contract with such Indian tribe or tribal organization."],[0,"(f) Eligible Indian"],[0,"For purposes of this section, the term \"eligible Indian\" means any Indian who is eligible for health services provided by the Service without regard to the provisions of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1680c?type=usc&year=mostrecent&link-type=html"},"head":"§1680c. Health services for ineligible persons","tname":"Indians","by":{"0":"2, 2, 2","1":"35","2":"43","3":"19, 19, 19"}},{"t":"usc","label":"25 U.S.C. § 5301","url":"https://www.law.cornell.edu/uscode/text/25/5301","subs":["(a)(1)"],"stext":{"head":"§5301. Congressional statement of findings","paras":[[0,"(a) Findings respecting historical and special legal relationship, and resultant responsibilities"],[0,"The Congress, after careful review of the Federal Government's historical and special legal relationship with, and resulting responsibilities to, American Indian people, finds that—"],[1,"(1) the prolonged Federal domination of Indian service programs has served to retard rather than enhance the progress of Indian people and their communities by depriving Indians of the full opportunity to develop leadership skills crucial to the realization of self-government, and has denied to the Indian people an effective voice in the planning and implementation of programs for the benefit of Indians which are responsive to the true needs of Indian communities; and"],[1,"(2) the Indian people will never surrender their desire to control their relationships both among themselves and with non-Indian governments, organizations, and persons."],[0,"(b) Further findings"],[0,"The Congress further finds that—"],[1,"(1) true self-determination in any society of people is dependent upon an educational process which will insure the development of qualified people to fulfill meaningful leadership roles;"],[1,"(2) the Federal responsibility for and assistance to education of Indian children has not effected the desired level of educational achievement or created the diverse opportunities and personal satisfaction which education can and should provide; and"],[1,"(3) parental and community control of the educational process is of crucial importance to the Indian people."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5301?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5301. Congressional statement of findings","tname":"Indians","by":{"0":"2","1":"1, 4","2":"1"}},{"t":"usc","label":"25 U.S.C. § 450","url":"https://www.law.cornell.edu/uscode/text/25/450","by":{"0":"2"}},{"t":"usc","label":"25 U.S.C. § 5302","url":"https://www.law.cornell.edu/uscode/text/25/5302","subs":["(b)","(a)"],"stext":{"head":"§5302. Congressional declaration of policy","paras":[[0,"(a) Recognition of obligation of United States"],[0,"The Congress hereby recognizes the obligation of the United States to respond to the strong expression of the Indian people for self-determination by assuring maximum Indian participation in the direction of educational as well as other Federal services to Indian communities so as to render such services more responsive to the needs and desires of those communities."],[0,"(b) Declaration of commitment"],[0,"The Congress declares its commitment to the maintenance of the Federal Government's unique and continuing relationship with, and responsibility to, individual Indian tribes and to the Indian people as a whole through the establishment of a meaningful Indian self-determination policy which will permit an orderly transition from the Federal domination of programs for, and services to, Indians to effective and meaningful participation by the Indian people in the planning, conduct, and administration of those programs and services. In accordance with this policy, the United States is committed to supporting and assisting Indian tribes in the development of strong and stable tribal governments, capable of administering quality programs and developing the economies of their respective communities."],[0,"(c) Declaration of national goal"],[0,"The Congress declares that a major national goal of the United States is to provide the quantity and quality of educational services and opportunities which will permit Indian children to compete and excel in the life areas of their choice, and to achieve the measure of self-determination essential to their social and economic well-being."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5302?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5302. Congressional declaration of policy","tname":"Indians","by":{"0":"3","1":"4","2":"4"}},{"t":"usc","label":"25 U.S.C. § 5304","url":"https://www.law.cornell.edu/uscode/text/25/5304","subs":["(c)","(f)"],"by":{"0":"3","2":"22, 20"}},{"t":"usc","label":"25 U.S.C. § 5321","url":"https://www.law.cornell.edu/uscode/text/25/5321","subs":["(g)","(a)(1)","(f)"],"stext":{"head":"§5321. Self-determination contracts","paras":[[0,"(a) Request by tribe; authorized programs"],[0,"(1) The Secretary is directed, upon the request of any Indian tribe by tribal resolution, to enter into a self-determination contract or contracts with a tribal organization to plan, conduct, and administer programs or portions thereof, including construction programs—"],[1,"(A) provided for in the Act of April 16, 1934 (48 Stat. 596), as amended [25 U.S.C. 5342 et seq.];"],[1,"(B) which the Secretary is authorized to administer for the benefit of Indians under the Act of November 2, 1921 (42 Stat. 208) [25 U.S.C. 13], and any Act subsequent thereto;"],[1,"(C) provided by the Secretary of Health and Human Services under the Act of August 5, 1954 (68 Stat. 674), as amended [42 U.S.C. 2001 et seq.];"],[1,"(D) administered by the Secretary for the benefit of Indians for which appropriations are made to agencies other than the Department of Health and Human Services or the Department of the Interior; and"],[1,"(E) for the benefit of Indians because of their status as Indians without regard to the agency or office of the Department of Health and Human Services or the Department of the Interior within which it is performed."],[0,"The programs, functions, services, or activities that are contracted under this paragraph shall include administrative functions of the Department of the Interior and the Department of Health and Human Services (whichever is applicable) that support the delivery of services to Indians, including those administrative activities supportive of, but not included as part of, the service delivery programs described in this paragraph that are otherwise contractable. The administrative functions referred to in the preceding sentence shall be contractable without regard to the organizational level within the Department that carries out such functions."],[0,"(2) If so authorized by an Indian tribe under paragraph (1) of this subsection, a tribal organization may submit a proposal for a self-determination contract, or a proposal to amend or renew a self-determination contract, to the Secretary for review. Subject to the provisions of paragraph (4), the Secretary shall, within ninety days after receipt of the proposal, approve the proposal and award the contract unless the Secretary provides written notification to the applicant that contains a specific finding that clearly demonstrates that, or that is supported by a controlling legal authority that—"],[1,"(A) the service to be rendered to the Indian beneficiaries of the particular program or function to be contracted will not be satisfactory;"],[1,"(B) adequate protection of trust resources is not assured;"],[1,"(C) the proposed project or function to be contracted for cannot be properly completed or maintained by the proposed contract;"],[1,"(D) the amount of funds proposed under the contract is in excess of the applicable funding level for the contract, as determined under section 5325(a) of this title; or"],[1,"(E) the program, function, service, or activity (or portion thereof) that is the subject of the proposal is beyond the scope of programs, functions, services, or activities covered under paragraph (1) because the proposal includes activities that cannot lawfully be carried out by the contractor."],[0,"Notwithstanding any other provision of law, the Secretary may extend or otherwise alter the 90-day period specified in the second sentence of this subsection,1 if before the expiration of such period, the Secretary obtains the voluntary and express written consent of the tribe or tribal organization to extend or otherwise alter such period. The contractor shall include in the proposal of the contractor the standards under which the tribal organization will operate the contracted program, service, function, or activity, including in the area of construction, provisions regarding the use of licensed and qualified architects, applicable health and safety standards, adherence to applicable Federal, State, local, or tribal building codes and engineering standards. The standards referred to in the preceding sentence shall ensure structural integrity, accountability of funds, adequate competition for subcontracting under tribal or other applicable law, the commencement, performance, and completion of the contract, adherence to project plans and specifications (including any applicable Federal construction guidelines and manuals), the use of proper materials and workmanship, necessary inspection and testing, and changes, modifications, stop work, and termination of the work when warranted."],[0,"(3) Upon the request of a tribal organization that operates two or more mature self-determination contracts, those contracts may be consolidated into one single contract."],[0,"(4) The Secretary shall approve any severable portion of a contract proposal that does not support a declination finding described in paragraph (2). If the Secretary determines under such paragraph that a contract proposal—"],[1,"(A) proposes in part to plan, conduct, or administer a program, function, service, or activity that is beyond the scope of programs covered under paragraph (1), or"],[1,"(B) proposes a level of funding that is in excess of the applicable level determined under section 5325(a) of this title,"],[0,"subject to any alteration in the scope of the proposal that the Secretary and the tribal organization agree to, the Secretary shall, as appropriate, approve such portion of the program, function, service, or activity as is authorized under paragraph (1) or approve a level of funding authorized under section 5325(a) of this title. If a tribal organization elects to carry out a severable portion of a contract proposal pursuant to this paragraph, subsection (b) of this section shall only apply to the portion of the contract that is declined by the Secretary pursuant to this subsection."],[0,"(b) Procedure upon refusal of request to contract"],[0,"Whenever the Secretary declines to enter into a self-determination contract or contracts pursuant to subsection (a) of this section, the Secretary shall—"],[1,"(1) state any objections in writing to the tribal organization,"],[1,"(2) provide assistance to the tribal organization to overcome the stated objections, and"],[1,"(3) provide the tribal organization with a hearing on the record with the right to engage in full discovery relevant to any issue raised in the matter and the opportunity for appeal on the objections raised, under such rules and regulations as the Secretary may promulgate, except that the tribe or tribal organization may, in lieu of filing such appeal, exercise the option to initiate an action in a Federal district court and proceed directly to such court pursuant to section 5331(a) of this title."],[0,"(c) Liability insurance; waiver of defense"],[0,"(1) Beginning in 1990, the Secretary shall be responsible for obtaining or providing liability insurance or equivalent coverage, on the most cost-effective basis, for Indian tribes, tribal organizations, and tribal contractors carrying out contracts, grant agreements and cooperative agreements pursuant to this chapter. In obtaining or providing such coverage, the Secretary shall take into consideration the extent to which liability under such contracts or agreements are covered by the Federal Tort Claims Act."],[0,"(2) In obtaining or providing such coverage, the Secretary shall, to the greatest extent practicable, give a preference to coverage underwritten by Indian-owned economic enterprises (as defined in section 1452 of this title), except that, for the purposes of this subsection, such enterprises may include non-profit corporations."],[0,"(3)(A) Any policy of insurance obtained or provided by the Secretary pursuant to this subsection shall contain a provision that the insurance carrier shall waive any right it may have to raise as a defense the sovereign immunity of an Indian tribe from suit, but that such waiver shall extend only to claims the amount and nature of which are within the coverage and limits of the policy and shall not authorize or empower such insurance carrier to waive or otherwise limit the tribe's sovereign immunity outside or beyond the coverage or limits of the policy of insurance."],[0,"(B) No waiver of the sovereign immunity of an Indian tribe pursuant to this paragraph shall include a waiver to the extent of any potential liability for interest prior to judgment or for punitive damages or for any other limitation on liability imposed by the law of the State in which the alleged injury occurs."],[0,"(d) Tribal organizations and Indian contractors deemed part of Public Health Service"],[0,"For purposes of section 233 of title 42, with respect to claims by any person, initially filed on or after December 22, 1987, whether or not such person is an Indian or Alaska Native or is served on a fee basis or under other circumstances as permitted by Federal law or regulations for personal injury, including death, resulting from the performance prior to, including, or after December 22, 1987, of medical, surgical, dental, or related functions, including the conduct of clinical studies or investigations, or for purposes of section 2679, title 28, with respect to claims by any such person, on or after November 29, 1990, for personal injury, including death, resulting from the operation of an emergency motor vehicle, an Indian tribe, a tribal organization or Indian contractor carrying out a contract, grant agreement, or cooperative agreement under sections 2 5321 or 5322 of this title is deemed to be part of the Public Health Service in the Department of Health and Human Services while carrying out any such contract or agreement and its employees (including those acting on behalf of the organization or contractor as provided in section 2671 of title 28 and including an individual who provides health care services pursuant to a personal services contract with a tribal organization for the provision of services in any facility owned, operated, or constructed under the jurisdiction of the Indian Health Service) are deemed employees of the Service while acting within the scope of their employment in carrying out the contract or agreement: Provided, That such employees shall be deemed to be acting within the scope of their employment in carrying out such contract or agreement when they are required, by reason of such employment, to perform medical, surgical, dental or related functions at a facility other than the facility operated pursuant to such contract or agreement, but only if such employees are not compensated for the performance of such functions by a person or entity other than such Indian tribe, tribal organization or Indian contractor."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5321?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§5321. Self-determination contracts","tname":"Indians","by":{"0":"3, 10","1":"24, 33, 10, 20, 46","2":"18, 53","3":"3"}},{"t":"usc","label":"25 U.S.C. § 5325","url":"https://www.law.cornell.edu/uscode/text/25/5325","subs":["(a)","(a)(1)","(a)(2)","(a)(2)(A)","(a)(2)(B)","(a)(3)","(a)(3)(A)","(a)(3)(A)(i)","(a)(3)(A)(ii)","(a)(3)(C)","(a)(4)","(a)(4)(A)","(e)","(k)(7)","(k)(8)","(k)(9)","(k)(11)","(m)","(m)(1)","(m)(2)","(a)(5)","(b)","(h)"],"stext":{"head":"§5325. Contract funding and indirect costs","paras":[[0,"(a) Amount of funds provided"],[0,"(1) The amount of funds provided under the terms of self-determination contracts entered into pursuant to this chapter shall not be less than the appropriate Secretary would have otherwise provided for the operation of the programs or portions thereof for the period covered by the contract, without regard to any organizational level within the Department of the Interior or the Department of Health and Human Services, as appropriate, at which the program, function, service, or activity or portion thereof, including supportive administrative functions that are otherwise contractable, is operated."],[0,"(2) There shall be added to the amount required by paragraph (1) contract support costs which shall consist of an amount for the reasonable costs for activities which must be carried on by a tribal organization as a contractor to ensure compliance with the terms of the contract and prudent management, but which—"],[1,"(A) normally are not carried on by the respective Secretary in his direct operation of the program; or"],[1,"(B) are provided by the Secretary in support of the contracted program from resources other than those under contract."],[0,"(3)(A) The contract support costs that are eligible costs for the purposes of receiving funding under this chapter shall include the costs of reimbursing each tribal contractor for reasonable and allowable costs of—"],[1,"(i) direct program expenses for the operation of the Federal program that is the subject of the contract; and"],[1,"(ii) any additional administrative or other expense incurred by the governing body of the Indian Tribe or Tribal organization and any overhead expense incurred by the tribal contractor in connection with the operation of the Federal program, function, service, or activity pursuant to the contract,"],[0,"except that such funding shall not duplicate any funding provided under subsection (a)(1) of this section."],[0,"(B) In calculating the reimbursement rate for expenses described in subparagraph (A)(ii), not less than 50 percent of the expenses described in subparagraph (A)(ii) that are incurred by the governing body of an Indian Tribe or Tribal organization relating to a Federal program, function, service, or activity carried out pursuant to the contract shall be considered to be reasonable and allowable."],[0,"(C) On an annual basis, during such period as a tribe or tribal organization operates a Federal program, function, service, or activity pursuant to a contract entered into under this chapter, the tribe or tribal organization shall have the option to negotiate with the Secretary the amount of funds that the tribe or tribal organization is entitled to receive under such contract pursuant to this paragraph."],[0,"(4) For each fiscal year during which a self-determination contract is in effect, any savings attributable to the operation of a Federal program, function, service, or activity under a self-determination contract by a tribe or tribal organization (including a cost reimbursement construction contract) shall—"],[1,"(A) be used to provide additional services or benefits under the contract; or"],[1,"(B) be expended by the tribe or tribal organization in the succeeding fiscal year, as provided in section 13a of this title."],[0,"(5) Subject to paragraph (6), during the initial year that a self-determination contract is in effect, the amount required to be paid under paragraph (2) shall include startup costs consisting of the reasonable costs that have been incurred or will be incurred on a one-time basis pursuant to the contract necessary—"],[1,"(A) to plan, prepare for, and assume operation of the program, function, service, or activity that is the subject of the contract; and"],[1,"(B) to ensure compliance with the terms of the contract and prudent management."],[0,"(6) Costs incurred before the initial year that a self-determination contract is in effect may not be included in the amount required to be paid under paragraph (2) if the Secretary does not receive a written notification of the nature and extent of the costs prior to the date on which such costs are incurred."],[0,"(b) Reductions and increases in amount of funds provided"],[0,"The amount of funds required by subsection (a) of this section—"],[1,"(1) shall not be reduced to make funding available for contract monitoring or administration by the Secretary;"],[1,"(2) shall not be reduced by the Secretary in subsequent years except pursuant to—"],[2,"(A) a reduction in appropriations from the previous fiscal year for the program or function to be contracted;"],[2,"(B) a directive in the statement of the managers accompanying a conference report on an appropriation bill or continuing resolution;"],[2,"(C) a tribal authorization;"],[2,"(D) a change in the amount of pass-through funds needed under a contract; or"],[2,"(E) completion of a contracted project, activity, or program;"],[1,"(3) shall not be reduced by the Secretary to pay for Federal functions, including, but not limited to, Federal pay costs, Federal employee retirement benefits, automated data processing, contract technical assistance or contract monitoring;"],[1,"(4) shall not be reduced by the Secretary to pay for the costs of Federal personnel displaced by a self-determination contract; and"],[1,"(5) may, at the request of the tribal organization, be increased by the Secretary if necessary to carry out this chapter or as provided in section 5324(c) of this title."],[0,"Notwithstanding any other provision in this chapter, the provision of funds under this chapter is subject to the availability of appropriations and the Secretary is not required to reduce funding for programs, projects, or activities serving a tribe to make funds available to another tribe or tribal organization under this chapter."],[0,"(c) Annual reports"],[0,"Not later than May 15 of each year, the Secretary shall prepare and submit to Congress an annual report on the implementation of this chapter. Such report shall include—"],[1,"(1) an accounting of the total amounts of funds provided for each program and the budget activity for direct program costs and contract support costs of tribal organizations under self-determination;"],[1,"(2) an accounting of any deficiency in funds needed to provide required contract support costs to all contractors for the fiscal year for which the report is being submitted;"],[1,"(3) the indirect cost rate and type of rate for each tribal organization that has been negotiated with the appropriate Secretary;"],[1,"(4) the direct cost base and type of base from which the indirect cost rate is determined for each tribal organization;"],[1,"(5) the indirect cost pool amounts and the types of costs included in the indirect cost pool; and"],[1,"(6) an accounting of any deficiency in funds needed to maintain the preexisting level of services to any Indian tribes affected by contracting activities under this chapter, and a statement of the amount of funds needed for transitional purposes to enable contractors to convert from a Federal fiscal year accounting cycle, as authorized by section 5324(d) of this title."],[0,"(d) Treatment of shortfalls in indirect cost recoveries"],[0,"(1) Where a tribal organization's allowable indirect cost recoveries are below the level of indirect costs that the tribal organizations should have received for any given year pursuant to its approved indirect cost rate, and such shortfall is the result of lack of full indirect cost funding by any Federal, State, or other agency, such shortfall in recoveries shall not form the basis for any theoretical over-recovery or other adverse adjustment to any future years' indirect cost rate or amount for such tribal organization, nor shall any agency seek to collect such shortfall from the tribal organization."],[0,"(2) Nothing in this subsection shall be construed to authorize the Secretary to fund less than the full amount of need for indirect costs associated with a self-determination contract."],[0,"(e) Liability for indebtedness incurred before fiscal year 1992"],[0,"Indian tribes and tribal organizations shall not be held liable for amounts of indebtedness attributable to theoretical or actual under-recoveries or theoretical over-recoveries of indirect costs, as defined in Office of Management and Budget Circular A–87, incurred for fiscal years prior to fiscal year 1992."],[0,"(f) Limitation on remedies relating to cost disallowances"],[0,"Any right of action or other remedy (other than those relating to a criminal offense) relating to any disallowance of costs shall be barred unless the Secretary has given notice of any such disallowance within three hundred and sixty-five days of receiving any required annual single agency audit report or, for any period covered by law or regulation in force prior to October 19, 1984, any other required final audit report. Such notice shall set forth the right of appeal and hearing to the board of contract appeals pursuant to section 5331 of this title. For the purpose of determining the 365-day period specified in this paragraph, an audit report shall be deemed to have been received on the date of actual receipt by the Secretary, if, within 60 days after receiving the report, the Secretary does not give notice of a determination by the Secretary to reject the single-agency report as insufficient due to noncompliance with chapter 75 of title 31 or noncompliance with any other applicable law. Nothing in this subsection shall be deemed to enlarge the rights of the Secretary with respect to section 5123 of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5325?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§5325. Contract funding and indirect costs","tname":"Indians","by":{"0":"39, 4, 5, 11, 15-17, 24, 25, 27, 36, 39, 4, 16, 20, 22, 24, 28, 4, 5, 12, 14-18, 21, 22, 24, 28, 30, 32-36, 40, 5, 21, 35, 36, 5, 21, 22, 35, 14, 15, 17, 22, 24, 27, 40, 6, 9, 15, 22, 35, 36, 6, 17, 18, 22, 32, 35-37, 6, 12, 17, 18, 22, 32, 35, 36, 38, 6, 24, 26, 33, 39, 26, 39, 39, 34, 26, 9, 23, 24, 33, 9, 23, 28, 33-35, 37, 39, 9, 11, 16, 23, 24","1":"3, 5, 33, 15, 18, 26, 27, 29, 27, 27, 3, 33, 10, 11, 26, 28, 22, 25, 2, 16, 17, 21, 22, 34, 12, 31, 36, 36, 23, 3, 11, 25, 2, 15, 16, 24, 25, 27, 34, 30, 34","2":"1, 6, 34, 1, 8, 17, 19-20, 30-34, 52, 55, 1, 9, 55, 9, 16-17, 19, 24-26, 30-32, 34, 36, 40, 52, 2, 20, 22-23, 28, 35, 54, 2, 20, 22, 28, 35, 54, 26, 27, 6, 19, 24, 36-37, 40, 2, 7, 15-16, 20-22, 24-29, 7, 29, 36-37, 54","3":"10, 13, 17, 2, 10, 2-4, 6-9, 21, 5, 3, 4, 8, 9, 7, 9, 13, 8, 9, 10, 12, 6, 21, 6, 2, 7, 11, 17, 5-7, 3, 11"}},{"t":"usc","label":"25 U.S.C. § 5326","url":"https://www.law.cornell.edu/uscode/text/25/5326","stext":{"head":"§5326. Indian Health Service: availability of funds for Indian self-determination or self-governance contract or grant support costs","paras":[[0,"Before, on, and after October 21, 1998, and notwithstanding any other provision of law, funds available to the Indian Health Service in this Act or any other Act for Indian self-determination or self-governance contract or grant support costs may be expended only for costs directly attributable to contracts, grants and compacts pursuant to the Indian Self-Determination Act [25 U.S.C. 5321 et seq.] and no funds appropriated by this or any other Act shall be available for any contract support costs or indirect costs associated with any contract, grant, cooperative agreement, self-governance compact, or funding agreement entered into between an Indian tribe or tribal organization and any entity other than the Indian Health Service."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5326?type=usc&year=mostrecent&link-type=html"},"op":20,"ar":1,"head":"§5326. Indian Health Service: availability of funds for Indian self-determination or self-governance contract or grant support costs","tname":"Indians","by":{"0":"8, 11, 13-18, 25-27, 40-42, 46","1":"14, 17, 20, 36, 41","2":"10, 18, 45-49, 51-52","3":"13-15, 17"}},{"t":"usc","label":"25 U.S.C. § 5327","url":"https://www.law.cornell.edu/uscode/text/25/5327","by":{"0":"8"}},{"t":"usc","label":"25 U.S.C. § 5329","url":"https://www.law.cornell.edu/uscode/text/25/5329","subs":["(c)","(a)","(a)(1)"],"stext":{"head":"§5329. Contract or grant specifications","paras":[[0,"(a) Terms"],[0,"Each self-determination contract entered into under this chapter shall—"],[1,"(1) contain, or incorporate by reference, the provisions of the model agreement described in subsection (c) of this section (with modifications where indicated and the blanks appropriately filled in), and"],[1,"(2) subject to subsections (a) and (b) of section 5321 of this title, contain such other provisions as are agreed to by the parties."],[0,"(b) Payments; Federal records"],[0,"Notwithstanding any other provision of law, the Secretary may make payments pursuant to section 1(b)(6) of such model agreement. As provided in section 1(b)(7) of the model agreement, the records of the tribal government or tribal organization specified in such section shall not be considered Federal records for purposes of chapter 5 of title 5."],[0,"(c) Model agreement"],[0,"The model agreement referred to in subsection (a)(1) of this section reads as follows:"],[0,"\"SECTION 1. AGREEMENT BETWEEN THE SECRETARY AND THE ____________ TRIBAL GOVERNMENT."],[0,"\"(a) Authority and Purpose.—"],[1,"\"(1) Authority.—This agreement, denoted a Self-Determination Contract (referred to in this agreement as the 'Contract'), is entered into by the Secretary of the Interior or the Secretary of Health and Human Services (referred to in this agreement as the 'Secretary'), for and on behalf of the United States pursuant to title I of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.) 1 and by the authority of the ____________ tribal government or tribal organization (referred to in this agreement as the 'Contractor'). The provisions of title I of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.) 1 are incorporated in this agreement."],[1,"\"(2) Purpose.—Each provision of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.) 1 and each provision of this Contract shall be liberally construed for the benefit of the Contractor to transfer the funding and the following related functions, services, activities, and programs (or portions thereof), that are otherwise contractable under section 102(a) of such Act, including all related administrative functions, from the Federal Government to the Contractor: (List functions, services, activities, and programs)."],[0,"\"(b) Terms, Provisions, and Conditions.—"],[1,"\"(1) Term.—Pursuant to section 105(c)(1) of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450j(c)(1)),1 the term of this contract shall be ____ years. Pursuant to section 105(d)(1) of such Act (25 U.S.C. 450j(d)) 1, upon the election by the Contractor, the period of this Contract shall be determined on the basis of a calendar year, unless the Secretary and the Contractor agree on a different period in the annual funding agreement incorporated by reference in subsection (f)(2)."],[1,"\"(2) Effective date.—This Contract shall become effective upon the date of the approval and execution by the Contractor and the Secretary, unless the Contractor and the Secretary agree on an effective date other than the date specified in this paragraph."],[1,"\"(3) Program standard.—The Contractor agrees to administer the program, services, functions and activities (or portions thereof) listed in subsection (a)(2) of the Contract in conformity with the following standards: (list standards)."],[1,"\"(4) Funding amount.—Subject to the availability of appropriations, the Secretary shall make available to the Contractor the total amount specified in the annual funding agreement incorporated by reference in subsection (f)(2). Such amount shall not be less than the applicable amount determined pursuant to section 106(a) of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450j–1).1"],[1,"\"(5) Limitation of costs.—The Contractor shall not be obligated to continue performance that requires an expenditure of funds in excess of the amount of funds awarded under this Contract. If, at any time, the Contractor has reason to believe that the total amount required for performance of this Contract or a specific activity conducted under this Contract would be greater than the amount of funds awarded under this Contract, the Contractor shall provide reasonable notice to the appropriate Secretary. If the appropriate Secretary does not take such action as may be necessary to increase the amount of funds awarded under this Contract, the Contractor may suspend performance of the Contract until such time as additional funds are awarded."],[1,"\"(6) Payment.—"],[2,"\"(A) In general.—Payments to the Contractor under this Contract shall—"],[3,"\"(i) be made as expeditiously as practicable; and"],[3,"\"(ii) include financial arrangements to cover funding during periods covered by joint resolutions adopted by Congress making continuing appropriations, to the extent permitted by such resolutions."],[2,"\"(B) Quarterly, semiannual, lump-sum, and other methods of payment.—"],[3,"\"(i) In general.—Pursuant to section 108(b) of the Indian Self-Determination and Education Assistance Act, and notwithstanding any other provision of law, for each fiscal year covered by this Contract, the Secretary shall make available to the Contractor the funds specified for the fiscal year under the annual funding agreement incorporated by reference pursuant to subsection (f)(2) by paying to the Contractor, on a quarterly basis, one-quarter of the total amount provided for in the annual funding agreement for that fiscal year, in a lump-sum payment or as semiannual payments, or any other method of payment authorized by law, in accordance with such method as may be requested by the Contractor and specified in the annual funding agreement."],[3,"\"(ii) Method of quarterly payment.—If quarterly payments are specified in the annual funding agreement incorporated by reference pursuant to subsection (f)(2), each quarterly payment made pursuant to clause (i) shall be made on the first day of each quarter of the fiscal year, except that in any case in which the Contract year coincides with the Federal fiscal year, payment for the first quarter shall be made not later than the date that is 10 calendar days after the date on which the Office of Management and Budget apportions the appropriations for the fiscal year for the programs, services, functions, and activities subject to this Contract."],[3,"\"(iii) Applicability.—Chapter 39 of title 31, United States Code, shall apply to the payment of funds due under this Contract and the annual funding agreement referred to in clause (i)."],[1,"\"(7) Records and monitoring.—"],[2,"\"(A) In general.—Except for previously provided copies of tribal records that the Secretary demonstrates are clearly required to be maintained as part of the recordkeeping system of the Department of the Interior or the Department of Health and Human Services (or both), records of the Contractor shall not be considered Federal records for purposes of chapter 5 of title 5, United States Code."],[2,"\"(B) Recordkeeping system.—The Contractor shall maintain a recordkeeping system and, upon reasonable advance request, provide reasonable access to such records to the Secretary."],[2,"\"(C) Responsibilities of contractor.—The Contractor shall be responsible for managing the day-to-day operations conducted under this Contract and for monitoring activities conducted under this Contract to ensure compliance with the Contract and applicable Federal requirements. With respect to the monitoring activities of the Secretary, the routine monitoring visits shall be limited to not more than two performance monitoring visits for this Contract by the head of each operating division, departmental bureau, or departmental agency, or duly authorized representative of such head unless—"],[3,"\"(i) the Contractor agrees to one or more additional visits; or"],[3,"\"(ii) the appropriate official determines that there is reasonable cause to believe that grounds for reassumption of the Contract, suspension of Contract payments, or other serious Contract performance deficiency may exist."],[2,"No additional visit referred to in clause (ii) shall be made until such time as reasonable advance notice that includes a description of the nature of the problem that requires the additional visit has been given to the Contractor."],[1,"\"(8) Property.—"],[2,"\"(A) In general.—As provided in section 105(f) of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450j(f)),1 at the request of the Contractor, the Secretary may make available, or transfer to the Contractor, all reasonably divisible real property, facilities, equipment, and personal property that the Secretary has used to provide or administer the programs, services, functions, and activities covered by this Contract. A mutually agreed upon list specifying the property, facilities, and equipment so furnished shall also be prepared by the Secretary, with the concurrence of the Contractor, and periodically revised by the Secretary, with the concurrence of the Contractor."],[2,"\"(B) Records.—The Contractor shall maintain a record of all property referred to in subparagraph (A) or other property acquired by the Contractor under section 105(f)(2)(A) of such Act for purposes of replacement."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5329?type=usc&year=mostrecent&link-type=html"},"head":"§5329. Contract or grant specifications","tname":"Indians","by":{"0":"10","1":"10, 10, 15, 10, 15, 23, 24, 46","2":"12, 3, 14, 23, 52, 35","3":"6, 10, 12"}},{"t":"usc","label":"25 U.S.C. § 5331","url":"https://www.law.cornell.edu/uscode/text/25/5331","subs":["(a)"],"by":{"0":"10, 13"}},{"t":"usc","label":"25 U.S.C. § 5381","url":"https://www.law.cornell.edu/uscode/text/25/5381","by":{"0":"3"}},{"t":"usc","label":"25 U.S.C. § 5388","url":"https://www.law.cornell.edu/uscode/text/25/5388","subs":["(c)","(h)","(j)"],"stext":{"head":"§5388. Transfer of funds","paras":[[0,"(a) In general"],[0,"Pursuant to the terms of any compact or funding agreement entered into under this subchapter, the Secretary shall transfer to the Indian tribe all funds provided for in the funding agreement, pursuant to subsection (c) of this section, and provide funding for periods covered by joint resolution adopted by Congress making continuing appropriations, to the extent permitted by such resolutions. In any instance where a funding agreement requires an annual transfer of funding to be made at the beginning of a fiscal year, or requires semiannual or other periodic transfers of funding to be made commencing at the beginning of a fiscal year, the first such transfer shall be made not later than 10 days after the apportionment of such funds by the Office of Management and Budget to the Department, unless the funding agreement provides otherwise."],[0,"(b) Multiyear funding"],[0,"The Secretary is authorized to employ, upon tribal request, multiyear funding agreements. References in this subchapter to funding agreements shall include such multiyear funding agreements."],[0,"(c) Amount of funding"],[0,"The Secretary shall provide funds under a funding agreement under this subchapter in an amount equal to the amount that the Indian tribe would have been entitled to receive under self-determination contracts under this chapter, including amounts for direct program costs specified under section 5325(a)(1) of this title and amounts for contract support costs specified under section 5325(a)(2), (3), (5), and (6) of this title, including any funds that are specifically or functionally related to the provision by the Secretary of services and benefits to the Indian tribe or its members, all without regard to the organizational level within the Department where such functions are carried out."],[0,"(d) Prohibitions"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), the Secretary is expressly prohibited from—"],[2,"(A) failing or refusing to transfer to an Indian tribe its full share of any central, headquarters, regional, area, or service unit office or other funds due under this chapter, except as required by Federal law;"],[2,"(B) withholding portions of such funds for transfer over a period of years; and"],[2,"(C) reducing the amount of funds required under this chapter—"],[3,"(i) to make funding available for self-governance monitoring or administration by the Secretary;"],[3,"(ii) in subsequent years, except pursuant to—"],[4,"(I) a reduction in appropriations from the previous fiscal year for the program or function to be included in a compact or funding agreement;"],[4,"(II) a congressional directive in legislation or accompanying report;"],[4,"(III) a tribal authorization;"],[4,"(IV) a change in the amount of pass-through funds subject to the terms of the funding agreement; or"],[4,"(V) completion of a project, activity, or program for which such funds were provided;"],[3,"(iii) to pay for Federal functions, including Federal pay costs, Federal employee retirement benefits, automated data processing, technical assistance, and monitoring of activities under this chapter; or"],[3,"(iv) to pay for costs of Federal personnel displaced by self-determination contracts under this chapter or self-governance;"],[0,"(2) Exception"],[1,"The funds described in paragraph (1)(C) may be increased by the Secretary if necessary to carry out this chapter or as provided in section 5324(c)(2) of this title."],[0,"(e) Other resources"],[0,"In the event an Indian tribe elects to carry out a compact or funding agreement with the use of Federal personnel, Federal supplies (including supplies available from Federal warehouse facilities), Federal supply sources (including lodging, airline transportation, and other means of transportation including the use of interagency motor pool vehicles) or other Federal resources (including supplies, services, and resources available to the Secretary under any procurement contracts in which the Department is eligible to participate), the Secretary shall acquire and transfer such personnel, supplies, or resources to the Indian tribe."],[0,"(f) Reimbursement to Indian Health Service"],[0,"With respect to functions transferred by the Indian Health Service to an Indian tribe, the Indian Health Service shall provide goods and services to the Indian tribe, on a reimbursable basis, including payment in advance with subsequent adjustment. The reimbursements received from those goods and services, along with the funds received from the Indian tribe pursuant to this subchapter, may be credited to the same or subsequent appropriation account which provided the funding, such amounts to remain available until expended."],[0,"(g) Prompt Payment Act"],[0,"Chapter 39 of title 31 shall apply to the transfer of funds due under a compact or funding agreement authorized under this subchapter."],[0,"(h) Interest or other income on transfers"],[0,"An Indian tribe is entitled to retain interest earned on any funds paid under a compact or funding agreement to carry out governmental or health purposes and such interest shall not diminish the amount of funds the Indian tribe is authorized to receive under its funding agreement in the year the interest is earned or in any subsequent fiscal year. Funds transferred under this subchapter shall be managed using the prudent investment standard."],[0,"(i) Carryover of funds"],[0,"All funds paid to an Indian tribe in accordance with a compact or funding agreement shall remain available until expended. In the event that an Indian tribe elects to carry over funding from 1 year to the next, such carryover shall not diminish the amount of funds the Indian tribe is authorized to receive under its funding agreement in that or any subsequent fiscal year."],[0,"(j) Program income"],[0,"All Medicare, Medicaid, or other program income earned by an Indian tribe shall be treated as supplemental funding to that negotiated in the funding agreement. The Indian tribe may retain all such income and expend such funds in the current year or in future years except to the extent that the Indian Health Care Improvement Act (25 U.S.C. 1601 et seq.) provides otherwise for Medicare and Medicaid receipts. Such funds shall not result in any offset or reduction in the amount of funds the Indian tribe is authorized to receive under its funding agreement in the year the program income is received or for any subsequent fiscal year."],[0,"(k) Limitation of costs"],[0,"An Indian tribe shall not be obligated to continue performance that requires an expenditure of funds in excess of the amount of funds transferred under a compact or funding agreement. If at any time the Indian tribe has reason to believe that the total amount provided for a specific activity in the compact or funding agreement is insufficient the Indian tribe shall provide reasonable notice of such insufficiency to the Secretary. If the Secretary does not increase the amount of funds transferred under the funding agreement, the Indian tribe may suspend performance of the activity until such time as additional funds are transferred."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5388?type=usc&year=mostrecent&link-type=html"},"head":"§5388. Transfer of funds","tname":"Indians","by":{"0":"24, 25, 34, 9, 10, 14, 16, 24","1":"29, 32","2":"36","3":"3, 4, 17"}},{"t":"usc","label":"25 U.S.C. § 5396","url":"https://www.law.cornell.edu/uscode/text/25/5396","subs":["(a)"],"by":{"0":"24"}},{"t":"law","label":"Pub. L. No. 100-472","url":"https://www.govinfo.gov/link/statute/102/2292","by":{"0":"4"}},{"t":"law","label":"Pub. L. No. 103-413","url":"https://www.govinfo.gov/link/statute/108/4257","by":{"0":"5"}},{"t":"usc","label":"25 U.S.C. § 13","url":"https://www.law.cornell.edu/uscode/text/25/13","stext":{"head":"§13. Expenditure of appropriations by Bureau","paras":[[0,"The Bureau of Indian Affairs, under the supervision of the Secretary of the Interior, shall direct, supervise, and expend such moneys as Congress may from time to time appropriate, for the benefit, care, and assistance of the Indians throughout the United States for the following purposes:"],[0,"General support and civilization, including education."],[0,"For relief of distress and conservation of health."],[0,"For industrial assistance and advancement and general administration of Indian property."],[0,"For extension, improvement, operation, and maintenance of existing Indian irrigation systems and for development of water supplies."],[0,"For the enlargement, extension, improvement, and repair of the buildings and grounds of existing plants and projects."],[0,"For the employment of inspectors, supervisors, superintendents, clerks, field matrons, farmers, physicians, Indian police, Indian judges, and other employees."],[0,"For the suppression of traffic in intoxicating liquor and deleterious drugs."],[0,"For the purchase of horse-drawn and motor-propelled passenger-carrying vehicles for official use."],[0,"And for general and incidental expenses in connection with the administration of Indian affairs."],[0,"Notwithstanding any other provision of this section or any other law, postsecondary schools administered by the Secretary of the Interior for Indians, and which meet the definition of an \"institution of higher education\" under section 101 of the Higher Education Act of 1965 [20 U.S.C. 1001], shall be eligible to participate in and receive appropriated funds under any program authorized by the Higher Education Act of 1965 [20 U.S.C. 1001 et seq.] or any other applicable program for the benefit of institutions of higher education, community colleges, or postsecondary educational institutions."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/13?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§13. Expenditure of appropriations by Bureau","tname":"Indians","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 1395qq","url":"https://www.law.cornell.edu/uscode/text/42/1395qq","subs":["(a)"],"stext":{"head":"§1395qq. Indian Health Service facilities","paras":[[0,"(a) Eligibility for payments; conditions and requirements"],[0,"A hospital or skilled nursing facility of the Indian Health Service, whether operated by such Service or by an Indian tribe or tribal organization (as those terms are defined in section 1603 of title 25), shall be eligible for payments under this subchapter, notwithstanding sections 1395f(c) and 1395n(d) of this title, if and for so long as it meets all of the conditions and requirements for such payments which are applicable generally to hospitals or skilled nursing facilities (as the case may be) under this subchapter."],[0,"(b) Eligibility based on submission of plan to achieve compliance with conditions and requirements; twelve-month period"],[0,"Notwithstanding subsection (a), a hospital or skilled nursing facility of the Indian Health Service which does not meet all of the conditions and requirements of this subchapter which are applicable generally to hospitals or skilled nursing facilities (as the case may be), but which submits to the Secretary within six months after September 30, 1976, an acceptable plan for achieving compliance with such conditions and requirements, shall be deemed to meet such conditions and requirements (and to be eligible for payments under this subchapter), without regard to the extent of its actual compliance with such conditions and requirements, during the first 12 months after the month in which such plan is submitted."],[0,"(c) Payments into special fund for improvements to achieve compliance with conditions and requirements; certification of compliance by Secretary"],[0,"Notwithstanding any other provision of this subchapter, payments to which any hospital or skilled nursing facility of the Indian Health Service is entitled by reason of this section shall be placed in a special fund to be held by the Secretary and used by him (to such extent or in such amounts as are provided in appropriation Acts) exclusively for the purpose of making any improvements in the hospitals and skilled nursing facilities of such Service which may be necessary to achieve compliance with the applicable conditions and requirements of this subchapter. The preceding sentence shall cease to apply when the Secretary determines and certifies that substantially all of the hospitals and skilled nursing facilities of such Service in the United States are in compliance with such conditions and requirements."],[0,"(d) Report by Secretary; status of facilities in complying with conditions and requirements"],[0,"The annual report of the Secretary which is required by section 1671 of title 25 shall include (along with the matters specified in section 1643 of title 25) a detailed statement of the status of the hospitals and skilled nursing facilities of the Service in terms of their compliance with the applicable conditions and requirements of this subchapter and of the progress being made by such hospitals and facilities (under plans submitted under subsection (b) and otherwise) toward the achievement of such compliance."],[0,"(e) Services provided by Indian Health Service, Indian tribe, or tribal organization"],[0,"(1)(A) Notwithstanding section 1395n(d) of this title, subject to subparagraph (B), the Secretary shall make payment under part B to a hospital or an ambulatory care clinic (whether provider-based or freestanding) that is operated by the Indian Health Service or by an Indian tribe or tribal organization (as defined for purposes of subsection (a)) for services described in paragraph (2) (and for items and services furnished on or after January 1, 2005, all items and services for which payment may be made under part B) furnished in or at the direction of the hospital or clinic under the same situations, terms, and conditions as would apply if the services were furnished in or at the direction of such a hospital or clinic that was not operated by such Service, tribe, or organization."],[0,"(B) Payment shall not be made for services under subparagraph (A) to the extent that payment is otherwise made for such services under this subchapter."],[0,"(2) The services described in this paragraph are the following:"],[1,"(A) Services for which payment is made under section 1395w–4 of this title."],[1,"(B) Services furnished by a practitioner described in section 1395u(b)(18)(C) of this title for which payment under part B is made under a fee schedule."],[1,"(C) Services furnished by a physical therapist or occupational therapist as described in section 1395x(p) of this title for which payment under part B is made under a fee schedule."],[0,"(3) Subsection (c) shall not apply to payments made under this subsection."],[0,"(f) Cross reference"],[0,"For provisions relating to the authority of certain Indian tribes, tribal organizations, and Alaska Native health organizations to elect to directly bill for, and receive payment for, health care services provided by a hospital or clinic of such tribes or organizations and for which payment may be made under this subchapter, see section 1645 of title 25.1"]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395qq?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1395qq. Indian Health Service facilities","tname":"The Public Health and Welfare","by":{"0":"9, 23","2":"5, 6, 21"}},{"t":"usc","label":"42 U.S.C. § 1396j","url":"https://www.law.cornell.edu/uscode/text/42/1396j","subs":["(a)"],"by":{"0":"9, 23","2":"5, 6, 21"}},{"t":"reg","label":"25 C.F.R. § 900.114","url":"https://www.ecfr.gov/current/title-25/section-900.114","by":{"0":"33"}},{"t":"case","label":"Bloate v. United States","cite":"559 U.S. 196","y":2010,"id":"2009/08-728","sc":1,"sum":"The Court held that the time granted to prepare pretrial motions is not automatically granted exclusion from the Speedy Trial Act's 70-day time limit.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"sum":"The Court held that, under 21 U.S.C. § 841(b) of the statute regarding drug-related deaths, an individual convicted of the death of another through the sale of drugs cannot be convicted of drug-induced homicide if multiple drugs are present in the deceased's system.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Christopher v. SmithKline Beecham Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"sum":"The Court held that the Secretary of Labor's definition of \"outside salesman\" apply to pharmaceutical sales representatives under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Cnty. of Yakima v. Confederated Tribes & Bands of Yakima Indian Nation","cite":"502 U.S. 251","y":1992,"id":"1991/90-408","sc":1,"sum":"The Indian General Allotment Act of 1887 permits Yakima County to impose an ad valorem tax on reservation land patented in fee pursuant to the Act and owned by reservation Indians or the Yakima Indian Nation itself, but does not allow the county to enforce its excise tax on sales of such land.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45","2":"51"}},{"t":"case","label":"FERC v. Elec. Power Supply Ass’n","cite":"577 U.S. 260","y":2016,"id":"2015/14-840","sc":1,"sum":"The Court held that the Federal Power Act (FPA) grants the Federal Energy Regulatory Commission (FERC) the authority to regulate wholesale market operators’ compensation for reduction in electricity consumption, and the rule in question was not arbitrary and capricious.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"HollyFrontier Cheyenne Refin., LLC v. Renewable Fuels Ass’n","cite":"141 S. Ct. 2172","y":2021,"id":"2020/20-472","sc":1,"sum":"Under the renewable fuel program’s fuel blending requirements for domestic refineries, a small refinery that previously received a hardship exemption may obtain an “extension” under 42 U. S. C. §7545(o)(9)(B)(i) even if the refinery did not seek a hardship exemption every year after initially doing so.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"28"}},{"t":"case","label":"Jamestown S’Klallam Tribe v. Azar","cite":"486 F. Supp. 3d 83","y":2020,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/486/83/","ar":1,"sum":"Noting that the patient base for the tribally operated facility in that case was 97% non-Indian.","sumSrc":"brief:3","by":{"1":"35","3":"20"}},{"t":"case","label":"McGirt v. Oklahoma","cite":"140 S. Ct. 2452","y":2020,"id":"2019/18-9526","sc":1,"sum":"The Court held that parts of eastern Oklahoma are an Indian reservation subject to exclusive federal jurisdiction for certain crimes under the Indian Major Crimes Act.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Mont v. United States","cite":"139 S. Ct. 1826","y":2019,"id":"2018/17-8995","sc":1,"sum":"Pretrial detention later credited as time served for a new conviction tolls a supervised-release term under 18 U. S. C. §3624(e), even if the court must make the tolling calculation after learning whether the time will be credited.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22"}},{"t":"case","label":"Okla. Tax Comm’n v. Citizen Band of Potawatomi Indian Tribe of Okla.","cite":"498 U.S. 505","y":1991,"id":"1990/89-1322","sc":1,"sum":"Under the doctrine of tribal sovereign immunity, a State that has not asserted jurisdiction over Indian lands under Public Law 280 may not tax sales of goods to tribesmen occurring on land held in trust for a federally recognized Indian tribe, but is free to collect taxes on such sales to nonmembers of the tribe.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Sandoz Inc. v. Amgen Inc.","cite":"582 U.S. 1","y":2017,"id":"2016/15-1039","sc":1,"sum":"The Court determined that the Biologics Price Competition and Innovation Act of 2009 allows for commercial notice of a “biosimilar product” to be effective if given prior to approval by the Food and Drug Administration (FDA), but that the Act’s notice requirement is not enforceable with an injunction.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"United States v. Jicarilla Apache Nation","cite":"564 U.S. 162","y":2011,"id":"2010/10-382","sc":1,"sum":"The Court held that the fiduciary exception to the attorney-client privilege does not apply to the general trust relationship between the United States and the Indian Tribes.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"United States v. Lara","cite":"541 U.S. 193","y":2004,"id":"2003/03-107","sc":1,"sum":"In an opinion written by Justice Stephen G. Breyer and joined by Chief Justice Rehnquist and three other Justices, the Court found that the right to prosecute nonmember Indians is inherent in the sovereignty of Native American tribes.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Ysleta del Sur Pueblo v. Texas","cite":"596 U.S. 685","y":2022,"id":"2021/20-493","sc":1,"sum":"The federal legislation at issue—the Ysleta del Sur and Alabama and Coushatta Indian Tribes of Texas Restoration Act—bans as a matter of federal law on tribal lands only those gaming activities also banned in Texas.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20, 45, 47"}},{"t":"usc","label":"25 U.S.C. § 1616a","url":"https://www.law.cornell.edu/uscode/text/25/1616a","subs":["(k)(1)"],"by":{"1":"32"}},{"t":"usc","label":"25 U.S.C. § 1616c","url":"https://www.law.cornell.edu/uscode/text/25/1616c","subs":["(b)(2)"],"by":{"1":"33"}},{"t":"usc","label":"25 U.S.C. § 1616q","url":"https://www.law.cornell.edu/uscode/text/25/1616q","by":{"1":"33"}},{"t":"usc","label":"25 U.S.C. § 1621","url":"https://www.law.cornell.edu/uscode/text/25/1621","subs":["(e)"],"by":{"1":"33"}},{"t":"usc","label":"25 U.S.C. § 1623","url":"https://www.law.cornell.edu/uscode/text/25/1623","subs":["(b)"],"by":{"1":"6, 8, 24","2":"6, 13, 21"}},{"t":"usc","label":"25 U.S.C. § 1631","url":"https://www.law.cornell.edu/uscode/text/25/1631","subs":["(c)(1)(C)"],"by":{"1":"8, 33"}},{"t":"usc","label":"25 U.S.C. § 1645","url":"https://www.law.cornell.edu/uscode/text/25/1645","subs":["(c)"],"by":{"1":"7, 33"}},{"t":"usc","label":"25 U.S.C. § 1680a","url":"https://www.law.cornell.edu/uscode/text/25/1680a","by":{"1":"33"}},{"t":"usc","label":"25 U.S.C. § 5361","url":"https://www.law.cornell.edu/uscode/text/25/5361","subs":["(8)"],"by":{"1":"24"}},{"t":"usc","label":"42 U.S.C. § 254b","url":"https://www.law.cornell.edu/uscode/text/42/254b","by":{"1":"39"}},{"t":"law","label":"Pub. L. No. 93-638","url":"https://www.govinfo.gov/link/statute/88/2203","by":{"1":"4, 5"}},{"t":"law","label":"Pub. L. No. 94-437","url":"https://www.govinfo.gov/link/statute/90/1400","by":{"1":"6"}},{"t":"law","label":"Pub. L. No. 100-713","url":"https://www.govinfo.gov/link/statute/102/4784","by":{"1":"6, 7"}},{"t":"law","label":"Pub. L. No. 102-573","url":"https://www.govinfo.gov/link/statute/106/4526","by":{"1":"7"}},{"t":"law","label":"Pub. L. No. 106-417","url":"https://www.govinfo.gov/link/plaw/106/public/417","by":{"1":"7"}},{"t":"case","label":"Bradley v. School Board of City of Richmond","cite":"416 U.S. 696","y":1974,"id":"1973/72-1322","sc":1,"sum":"Section 718 can be applied to attorneys' services that were rendered before that provision was enacted, in a situation like the one here involved where the propriety of the fee award was pending resolution on appeal when the statute became law.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"53"}},{"t":"case","label":"Landgraf v. USI Film Products","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"53"}},{"t":"case","label":"Maine Community Health Options v. United States","cite":"140 S. Ct. 1308","y":2020,"id":"2019/18-1023","sc":1,"sum":"The Court held that the federal government has an obligation to pay the insurance carriers in this case for losses incurred under the \"Risk Corridors\" program of the Affordable Care Act as a result of their participation in the health care marketplace.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Minnesota v. Mille Lacs Band of Chippewa Indians","cite":"526 U.S. 172","y":1999,"id":"1998/97-1337","sc":1,"sum":"Authored by Justice Sandra Day O'Connor, the Court ruled that the Mille Lacs Band of Chippewa Indians does have usufructuary rights that were guaranteed to them by the 1837 treaty.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Yellen v. Confederated Tribes of Chehalis Reservation","cite":"141 S. Ct. 2434","y":2021,"id":"2020/20-543","sc":1,"sum":"Alaska Native Corporations are “Indian tribe[s]” under the Indian Self-Determination and Education Assistance Act and thus eligible for funding available to “Tribal governments” under Title V of the Coronavirus Aid, Relief, and Economic Security Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"4"}},{"t":"usc","label":"28 U.S.C. § 1442","url":"https://www.law.cornell.edu/uscode/text/28/1442","subs":["(d)(5)"],"by":{"2":"31"}},{"t":"usc","label":"38 U.S.C. § 1984","url":"https://www.law.cornell.edu/uscode/text/38/1984","subs":["(i)"],"by":{"2":"47"}},{"t":"usc","label":"41 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/41/7101","by":{"2":"14"}},{"t":"law","label":"PROGRESS for Indian Tribes Act, Pub. L. No. 116-180","url":"https://www.govinfo.gov/link/plaw/116/public/180","by":{"2":"9"}},{"t":"reg","label":"2 C.F.R. pt. 200","url":"https://www.ecfr.gov/current/title-2/part-200","by":{"2":"44","3":"21"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"18, 19"}},{"t":"case","label":"Boechler, P.C. v. Commissioner","cite":"596 U.S. 199","y":2022,"id":"2021/20-1472","sc":1,"sum":"The 30-day time limit to file a petition for review of a collection due process determination, 26 U. S. C. §6330(d)(1), is a nonjurisdictional deadline subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"18"}},{"t":"case","label":"Department of Agric. Rural Dev. Rural Hous. Serv. v. Kirtz","cite":"144 S. Ct. 457","y":2024,"id":"2023/22-846","sc":1,"sum":"A consumer may sue a federal agency under 15 U. S. C. §§1681n and 1681o for defying the terms of the Fair Credit Reporting Act.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"16"}},{"t":"case","label":"DePierre v. United States","cite":"564 U.S. 70","y":2011,"id":"2010/09-1533","sc":1,"sum":"The Court held that the term \"cocaine base\" encompasses every form of cocaine that is classified chemically as a base.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"(I) Cases—Continued: Lac du Flambeau Band of Lake Superior Chippewa Indians v. Coughlin","cite":"599 U.S. 382","y":2023,"id":"2022/22-227","sc":1,"sum":"The Bankruptcy Code unequivocally abrogates the sovereign immunity of all governments, including federally recognized Indian tribes.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"18"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"Shady Grove Orthopedic Assocs., P.A. v. Allstate Ins. Co.","cite":"559 U.S. 393","y":2010,"id":"2009/08-1008","sc":1,"sum":"The Court held that Section 901(b) of the New York Rules of Civil Procedure does not preclude a federal court ruling on entities from different jurisdictions from hearing a class action under Rule 23 of the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"usc","label":"25 U.S.C. § 5235","url":"https://www.law.cornell.edu/uscode/text/25/5235","subs":["(a)(2)(B)"],"by":{"3":"5"}}]};